:root {
  --paper: #fffdf8;
  --ink: #202b3a;
  --navy: #29456f;
  --muted: #667386;
  --line: #d9e0e8;
  --cream: #f4ead6;
  --mist: #f3f6fa;
  --coral: #b65b57;
}

.match-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-top: 5px solid var(--navy);
  border-radius: 14px;
  background-color: var(--paper);
  color: var(--ink);
}

.match-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 16px;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 1.1px;
  text-transform: uppercase;
}

.round {
  padding: 5px 8px;
  border-radius: 999px;
  background-color: var(--cream);
  color: var(--navy);
  font-size: 11px;
  font-weight: 750;
}

.players {
  display: grid;
  grid-template-columns: 1fr 34px 1fr;
  align-items: stretch;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background-color: var(--mist);
}

.player {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  padding: 11px 14px;
}

.piece {
  display: grid;
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  background-color: var(--paper);
  color: var(--navy);
  font-size: 20px;
  line-height: 1;
}

.piece-dark {
  background-color: var(--navy);
  border-color: var(--navy);
  color: var(--paper);
}

.player-name {
  margin: 0;
  overflow: hidden;
  font-size: 14px;
  font-weight: 750;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rating {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.versus {
  align-self: center;
  color: var(--coral);
  font-size: 11px;
  font-weight: 800;
  text-align: center;
  text-transform: uppercase;
}

.match-details {
  display: grid;
  grid-template-columns: 1fr 1fr;
  padding: 0 16px;
}

.detail {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  padding: 10px 0;
}

.detail + .detail {
  padding-left: 18px;
  border-left: 1px solid var(--line);
}

.detail-label {
  color: var(--muted);
  font-size: 11px;
  font-weight: 650;
}

.detail-value {
  color: var(--ink);
  font-size: 14px;
  line-height: 1.2;
}

.match-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
}

.clock {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  font-weight: 650;
}

.confirm {
  padding: 7px 11px;
  border: 0;
  border-radius: 7px;
  background-color: var(--coral);
  color: var(--paper);
  font: inherit;
  font-size: 12px;
  font-weight: 750;
}
